RETURNS TRIGGER
LANGUAGE plpgsql
AS $$
BEGIN
  IF NEW.zone_radius_km IS NOT NULL THEN
    NEW.service_radius := NEW.zone_radius_km;
  END IF;
  RETURN NEW;
END;
$$;

